{
  "name": "@sublang/cligent",
  "version": "0.39.0",
  "description": "Unified TypeScript SDK for AI coding agent CLIs (Claude Code, Codex CLI, Gemini CLI, Kimi Code, OpenCode, and more)",
  "type": "module",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/sublang-ai/cligent.git"
  },
  "homepage": "https://github.com/sublang-ai/cligent#readme",
  "bugs": "https://github.com/sublang-ai/cligent/issues",
  "keywords": [
    "ai",
    "agent",
    "cli",
    "claude",
    "codex",
    "gemini",
    "kimi",
    "opencode",
    "unified",
    "adapter"
  ],
  "files": [
    "bin/tmux-play.mjs",
    "dist",
    "docs",
    "LICENSE",
    "README.md"
  ],
  "bin": {
    "tmux-play": "./bin/tmux-play.mjs"
  },
  "sideEffects": false,
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./runtime-targets": {
      "import": "./dist/runtime-targets.js",
      "types": "./dist/runtime-targets.d.ts"
    },
    "./adapters/claude-code": {
      "import": "./dist/adapters/claude-code.js",
      "types": "./dist/adapters/claude-code.d.ts"
    },
    "./adapters/codex": {
      "import": "./dist/adapters/codex.js",
      "types": "./dist/adapters/codex.d.ts"
    },
    "./adapters/gemini": {
      "import": "./dist/adapters/gemini.js",
      "types": "./dist/adapters/gemini.d.ts"
    },
    "./adapters/kimi": {
      "import": "./dist/adapters/kimi.js",
      "types": "./dist/adapters/kimi.d.ts"
    },
    "./adapters/opencode": {
      "import": "./dist/adapters/opencode.js",
      "types": "./dist/adapters/opencode.d.ts"
    },
    "./tmux-play": {
      "import": "./dist/app/tmux-play/index.js",
      "types": "./dist/app/tmux-play/index.d.ts"
    },
    "./captains/fanout": {
      "import": "./dist/captains/fanout.js",
      "types": "./dist/captains/fanout.d.ts"
    }
  },
  "engines": {
    "node": ">=18.3.0"
  },
  "scripts": {
    "build": "node ./scripts/build.mjs",
    "lint": "eslint --config config/eslint.config.js .",
    "format": "prettier --config config/prettierrc.json --write .",
    "typecheck": "tsc --noEmit -p config/tsconfig.test.json",
    "test": "vitest run --config config/vitest.config.ts",
    "test:distributable": "node ./scripts/verify-distributable.mjs",
    "test:package": "node ./scripts/verify-package-output.mjs",
    "test:smoke": "vitest run --config config/vitest.smoke.config.ts",
    "test:acceptance": "vitest run --config config/vitest.acceptance.config.ts",
    "test:browser": "vitest run --config config/vitest.browser.config.ts",
    "test:approvals": "vitest run --config config/vitest.approvals.config.ts",
    "smoke:release": "npm run build && npm run test:package && npm run test:distributable && npm run test:smoke",
    "prepush": "bash scripts/prepush.sh",
    "tmux-play-dev": "node ./bin/tmux-play-dev.mjs",
    "prepack": "npm run build"
  },
  "peerDependencies": {
    "@anthropic-ai/claude-agent-sdk": ">=0.3.321",
    "@openai/codex-sdk": ">=0.159.1",
    "@opencode-ai/sdk": ">=1.18.29"
  },
  "peerDependenciesMeta": {
    "@anthropic-ai/claude-agent-sdk": {
      "optional": true
    },
    "@openai/codex-sdk": {
      "optional": true
    },
    "@opencode-ai/sdk": {
      "optional": true
    }
  },
  "devDependencies": {
    "@anthropic-ai/claude-agent-sdk": "0.3.325",
    "@modelcontextprotocol/sdk": "1.32.1",
    "@openai/codex-sdk": "0.159.1",
    "@opencode-ai/sdk": "1.18.33",
    "@types/node": "^25.9.5",
    "@typescript-eslint/eslint-plugin": "^8.63.0",
    "@typescript-eslint/parser": "^8.63.0",
    "dotenv": "^17.3.1",
    "eslint": "^10.14.0",
    "eslint-plugin-n": "^18.3.0",
    "prettier": "^3.9.5",
    "typescript": "^5.5.0",
    "vite": "^6.4.3",
    "vitest": "^4.1.11"
  },
  "pnpm": {
    "overrides": {
      "@hono/node-server": "2.1.6",
      "eslint>minimatch": "11.0.3",
      "@eslint/config-array>minimatch": "11.0.3",
      "@typescript-eslint/typescript-estree>minimatch": "11.0.3"
    }
  },
  "dependencies": {
    "@agentclientprotocol/sdk": "1.4.0",
    "@playwright/mcp": "0.0.77",
    "smol-toml": "1.9.1",
    "yaml": "^2.8.4",
    "zod": "4.6.6"
  },
  "overrides": {
    "eslint": {
      "minimatch": "11.0.3"
    },
    "@eslint/config-array": {
      "minimatch": "11.0.3"
    },
    "@typescript-eslint/typescript-estree": {
      "minimatch": "11.0.3"
    }
  }
}
